 "content": "def transform(grid):
    # Source words are the nonzero runs in the first and last rows.
    h, w = len(grid), len(grid[0])
    words = []
    for r in (0, h - 1):
        seq = [(c, v) for c, v in enumerate(grid[r]) if v]
        if seq:
            words.append(seq)
    out = [row[:] for row in grid]
    # Each isolated colored marker gets the source word containing its color,
    # aligned so the matching item occupies the marker's column.
    for r in range(1, h - 1):
        for c in range(w):
            v = grid[r][c]
            if not v:
                continue
            word = next((seq for seq in words if any(x == v for _, x in seq)), None)
            if word is None:
                continue
            idx = next(i for i, (_, x) in enumerate(word) if x == v)
            start = c - idx
            for j, (_, x) in enumerate(word):
                cc = start + j
                if 0 <= cc < w:
                    out[r][cc] = x
    return out

